  {"name": "Regensburg brewery beer", "type": "drink", "desc": "Local Kneitinger dark, Spital helles and Bischofshof lagers, plus Weltenburger monastery dunkel from just upriver.", "places": [{"name": "Brauerei Gaststätte Kneitinger", "area": "Arnulfsplatz", "note": "City brewery tap room; the Kneitinger Bock in spring is an institution."}, {"name": "Spitalgarten", "area": "Stadtamhof", "note": "Brewery beer garden on the Danube pouring its own Spital beers."}, {"name": "Alte Linde Biergarten", "area": "Danube island", "note": "Best beer-garden view of the old town skyline across the water."}]},
  {"name": "Coffee and hot chocolate at a 17th-century cafe", "type": "drink", "desc": "Regensburg claims Germany's oldest coffee house, still pouring rich hot chocolate and coffee with handmade confectionery.", "places": [{"name": "Café Prinzess", "area": "Rathausplatz", "note": "Trading since 1686, famous for its own chocolates and drinking chocolate."}, {"name": "Café Orphée", "area": "Untere Bachgasse", "note": "French-style bistro cafe, a long-standing old-town coffee stop."}, {"name": "Haus Heuport", "area": "Domplatz", "note": "Cathedral-view cafe terrace for coffee and cake in the historic centre."}]}
